define(["jquery"],function($){let apiPromise;const loadApi=()=>{if(window.YT&&window.YT.Player){return Promise.resolve(window.YT)}if(apiPromise){return apiPromise}apiPromise=new Promise((resolve,reject)=>{const previous=window.onYouTubeIframeAPIReady;window.onYouTubeIframeAPIReady=()=>{if(typeof previous==="function"){previous()}resolve(window.YT)};const script=document.createElement("script");script.src="https://www.youtube.com/iframe_api";script.onerror=reject;document.head.appendChild(script)});return apiPromise};class YoutubeAdapter{constructor(root,config){this.root=root;this.config=config;this.handlers={};this.lastTime=0;this.playing=false}initialise(){return loadApi().then(YT=>new Promise(resolve=>{this.player=new YT.Player("videoprogress-youtube-player",{host:this.config.youtubehost,videoId:this.config.youtubeid,playerVars:{playsinline:1,rel:0,modestbranding:1},events:{onReady:()=>{this.startTimer();resolve(this)},onStateChange:event=>this.stateChanged(event.data,YT),onPlaybackRateChange:()=>this.rateChanged()}})}))}stateChanged(state,YT){if(state===YT.PlayerState.PLAYING){this.playing=true;this.emit("play")}else if(state===YT.PlayerState.PAUSED){this.playing=false;this.emit("pause")}else if(state===YT.PlayerState.ENDED){this.playing=false;this.emit("ended")}}startTimer(){this.timer=window.setInterval(()=>{const current=this.getCurrentTime();if(this.playing&&Math.abs(current-this.lastTime)>Math.max(3,this.getPlaybackRate()*3)){this.emit("seek",current,this.lastTime)}if(this.playing){this.emit("timeupdate",current)}this.lastTime=current},500)}rateChanged(){const maximum=Number(this.config.maxplaybackrate||0);if(maximum>0&&this.getPlaybackRate()>maximum){const available=this.player.getAvailablePlaybackRates().filter(rate=>rate<=maximum);this.player.setPlaybackRate(available.pop()||1)}this.emit("ratechange",this.getPlaybackRate())}play(){this.player.playVideo();return Promise.resolve()}pause(){this.player.pauseVideo()}getCurrentTime(){return Number(this.player.getCurrentTime()||0)}getDuration(){return Number(this.player.getDuration()||0)}getPlaybackRate(){return Number(this.player.getPlaybackRate()||1)}seek(position){this.player.seekTo(Math.max(0,Number(position)),true)}onPlay(handler){this.on("play",handler)}onPause(handler){this.on("pause",handler)}onTimeUpdate(handler){this.on("timeupdate",handler)}onSeek(handler){this.on("seek",handler)}onEnded(handler){this.on("ended",handler)}onRateChange(handler){this.on("ratechange",handler)}on(name,handler){this.handlers[name]=(this.handlers[name]||[]).concat(handler)}emit(name,...args){(this.handlers[name]||[]).forEach(handler=>handler(...args))}}const create=(root,config)=>new YoutubeAdapter(root,config).initialise();return{create:create}});